// OWNER: t1a (wave 1). FROZEN after wave 1 merges — only t1a may change it, and
// only by raising it (plan §5, §8). A wave-2 builder blocked on a missing field
// adds it to a local type and files it; they do not edit this file.
//
// The four wave-2 evidence components agree on these signatures BEFORE any of
// them is written. Every interface and required field below is plan §5
// verbatim. Additions are all OPTIONAL and each carries a comment saying where
// its value comes from; a component may ignore any of them.
//
// API shapes come ONLY from @/lib/api-types (never src/api/** directly);
// enums and constants from @/lib/contracts. FindingProof is
// components.schemas.FindingProof; AuditEvent is plan §5's name for AuditItem,
// the element of GET /v1/audit → AuditList.items.

import type { AuditEvent, FindingProof } from '@/lib/api-types';
import type { SEVERITY_INPUTS, SeverityBand, STAGES, StageState } from '@/lib/contracts';

export type { AuditEvent, FindingProof };

export type Density = 'glyph' | 'compact' | 'detail';

/**
 * Optional pass-through to the <Exhibit> frame the component renders in
 * (@/components/chrome). Every evidence frame names its endpoint (design R10),
 * so each component should render one — defaults may be derived from its data.
 */
export interface EvidenceFrameProps {
  /** The frame's section index, e.g. "01" on the marketing hero, "04" on finding detail. */
  index?: string;
  /** The provenance line, e.g. "GET /v1/reviews/4e8b1d0/result → findings[0].proof". */
  provenance?: string;
  /** ISO 8601 UTC with Z; printed as "captured <ISO>" in the provenance strip. */
  capturedAt?: string;
  /** The data is fixture-only (plan A11); the provenance line then says so. */
  ext?: boolean;
}

export interface ProofBenchProps extends EvidenceFrameProps {
  proof: FindingProof;              // from the generated client
  density: Exclude<Density, 'glyph'>;
  mode?: 'static' | 'replay';       // 'static' renders frame 0 — this is the day-1 deliverable
  onReplayEnd?: () => void;
  /** Finding.id — the frame identifier ("finding a91f3c2e", first 8) and the copy target. */
  findingId?: string;
  /** PullRequestInfo.base_sha of the finding's review. FindingProof carries no SHAs. */
  baseSha?: string | null;
  /** PullRequestInfo.head_sha of the finding's review. */
  headSha?: string | null;
  /** Finding.blocking — whether the verdict rail ends "→ blocks merge". */
  blocking?: boolean;
  /** Finding.title — the claim the bench proves or refutes (struck through when disproven). */
  claim?: string;
}

export interface ContributionBarProps extends EvidenceFrameProps {
  score: number;
  inputs: Record<(typeof SEVERITY_INPUTS)[number], number>;
  weights: Record<(typeof SEVERITY_INPUTS)[number], number>;
  density: Density;
  /** FindingSeverity.band — the server's band; if absent, derive it from SEVERITY_THRESHOLDS. */
  band?: SeverityBand;
  /** FindingSeverity.explanation — the generated sentence whose clauses the segments underline on hover. */
  explanation?: string;
  /** Finding.id — the frame identifier. */
  findingId?: string;
}

export interface ChainRailProps extends EvidenceFrameProps {
  events: AuditEvent[];
  verified: boolean;
  brokenAtSeq?: number | null;
  tamperable?: boolean;             // false on marketing until T8 opts in
  /** AuditChain.checked — how many events the server verified. */
  checked?: number;
  /** AuditChain.first_seq / last_seq — the verified range, for the header ("1,428 events"). */
  firstSeq?: number | null;
  lastSeq?: number | null;
  /** audit (default) · suppressions — the ledger reuses the rail (dashboard §3c). */
  variant?: 'audit' | 'suppressions';
}

export interface StageRailProps extends EvidenceFrameProps {
  stages: { key: (typeof STAGES)[number]; state: StageState; ms?: number }[];
  orientation: 'horizontal' | 'vertical';
  mode: 'live' | 'replay' | 'static';
  /** ReviewStatus.stage_index — 1-based, rendered as a monotonic progress value (motion §4.9.1). */
  stageIndex?: number | null;
  /** ReviewStatus.seconds_since_heartbeat — drives the stale-heartbeat treatment past 10s / 20s (motion §4.9.3). */
  secondsSinceHeartbeat?: number | null;
}
